local KTool = CS.Engine.Lib.KTool
local KCookie = CS.Engine.Lib.KCookie
local UIEventProxy = CS.Engine.UI.UIEventProxy
local CDTimerModule = CS.Engine.Modules.CDTimerModule
------------ import ------------

local OneDay = 86400

---@class UIFightMapDailyTypeCell
---@field TextTime                      	UnityEngine.RectTransform               
---@field TimeGroup                     	UnityEngine.RectTransform               
---@field Text                          	UnityEngine.RectTransform               
---@field Lock                          	UnityEngine.RectTransform               
---@field TxtState                      	UnityEngine.RectTransform               
---@field TxtName                       	UnityEngine.RectTransform               
---@field ImgIcon                       	UnityEngine.RectTransform               
---@field ImSelect                      	UnityEngine.RectTransform                        
local UIFightMapDailyTypeCell = Class('UIFightMapDailyTypeCell')

function UIFightMapDailyTypeCell:__init()
    self._dailyDojo = nil
    self._dailyTypeVo = nil
    self.__countdown = nil
    self._cb = nil
end

function UIFightMapDailyTypeCell:__delete()
    self._dailyDojo = nil
    self._dailyTypeVo = nil
    self.__countdown = nil
    self._cb = nil
end

function UIFightMapDailyTypeCell:Awake()
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = Bind(self, self.OnDailyCellClickAction)
end

---@param data DailyTypeVo 配表数据
function UIFightMapDailyTypeCell:FreshNode(data, cb)
    self:RemoveCountDown()
    if not data then
        return
    end
    local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
    local vo =  QuestConfMgr:GetInstance():GetDailyQuestTypeVoByType(data.type)
    if not vo then
        return
    end
    self._dailyTypeVo = vo
    self._dailyDojo = data
    self._cb = cb

    self:FillCommon()
    self:FillOpenTime()
end

function UIFightMapDailyTypeCell:FillCommon()
    CfUtils.FillText(self.TxtName, self._dailyTypeVo.name)
    CfUtils.FillText(self.TxtState, self._dailyTypeVo.autoDesc)
    CfUtils.FillImage(self.ImgIcon, self._dailyTypeVo.battleSelectionItem)
end

--绘制活动时间
function UIFightMapDailyTypeCell:FillOpenTime()
    --增益活动开放
    local isUp = (checkNumber(self._dailyDojo.energyBoxRemainTime) > 0) 
    KTool.SetActive(self.TimeGroup, isUp)
    if isUp then
        CfUtils.FillText(self.TextTime, CfUtils.GetTimeHMS(self._dailyDojo.energyBoxRemainTime))
        ---倒计时的处理
        if checkNumber(self._dailyDojo.energyBoxRemainTime) > 0 then
            self:StartTimer(self._dailyDojo.energyBoxRemainTime)
        end        
    end

    --解锁
    local isUnLock = (checkNumber(self._dailyDojo.open) == 1 and checkNumber(self._dailyDojo.unlock) == 1)
    KTool.SetActive(self.Lock, not isUnLock)
    if not isUnLock then
        if checkNumber(self._dailyDojo.open) == 0 then
            CfUtils.FillText(self.Text, localize("本轮未开放"))
        else
            CfUtils.FillText(self.Text, GameUtils.GetUnlockDescr(checkString(self._dailyTypeVo.unlockType), checkString(self._dailyTypeVo.unlockNum)))
        end
    end
end

function UIFightMapDailyTypeCell:RefreshSelectImage(isTrue)
    KTool.SetActive(self.ImSelect, isTrue)
end

function UIFightMapDailyTypeCell:StartTimer(count)
    count = checkInt(count)
    self:RemoveCountDown()
    self.__countdown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._dailyDojo.energyBoxRemainTime = self._dailyDojo.energyBoxRemainTime - 1
        CfUtils.FillText(self.TextTime, CfUtils.GetTimeHMS(self._dailyDojo.energyBoxRemainTime))
        if self._dailyDojo.energyBoxRemainTime <= 0 then
            KTool.SetActive(self.TimeGroup, false)
            Events.Broadcast(Constants.EventNames.DailyQuestUpRefresh, {type = self._dailyDojo.type})
        end
    end, count, false, true)
end

--点击回调
function UIFightMapDailyTypeCell:OnDailyCellClickAction()
    if not self._dailyTypeVo or not self._dailyDojo then
        return
    end

    if self._cb then
        self:_cb()
    end
end

function UIFightMapDailyTypeCell:RemoveCountDown()
    if self.__countdown then
        CDTimerModule.GetInstance():RemoveCD(self.__countdown)
        self.__countdown = nil
    end
end

function UIFightMapDailyTypeCell:OnDestroy()
    self:RemoveCountDown()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFightMapDailyTypeCell
